set -euo pipefail
cd /opt/news-flow/current
/opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {createRequire} from 'node:module';import {createHash} from 'node:crypto';const require=createRequire('/opt/news-flow/current/package.json'),env=require('dotenv').parse(fs.readFileSync('/etc/news-flow/news.env')),ES=require('elasticsearch'),es=new ES.Client({host:env.ES5_HOST,apiVersion:'5.6',log:[],maxRetries:0,requestTimeout:20000}),r=JSON.parse(fs.readFileSync('/var/lib/news-flow/vnexpress-miss-20261123/audit.json'));try{const info=await es.info(),proof=JSON.parse(fs.readFileSync('/etc/news-flow/identity-proof.json')).summary;if(!proof.verified||!info.version.number.startsWith('5.6.')||createHash('sha256').update(info.cluster_uuid).digest('hex')!==proof.clusterFingerprint)throw Error('ES_IDENTITY_CHANGED');const doc=r.doc,exact=await es.get({index:doc._index,type:doc._type,id:doc._id,ignore:[404]}),hits=await es.search({index:doc._index,type:doc._type,body:{size:10,query:{term:{url:r.url}},_source:['url','title','publishedDate','siteName']}});console.log(JSON.stringify({found:exact.found,total:hits.hits.total,hits:hits.hits.hits}));fs.writeFileSync('/var/lib/news-flow/vnexpress-miss-20261123/es-before.json',JSON.stringify({found:exact.found,total:hits.hits.total,hits:hits.hits.hits},null,2));}finally{es.close();}
NODE
